def transform(grid):
    rows, cols = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            cells = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            objects.append(cells)
    objects.sort(key=lambda cells: min(c for _, c in cells))
    out = [row[:] for row in grid]
    n = len(objects)
    for i, cells in enumerate(objects):
        color = 8 if (n - 1 - i) % 2 == 0 else 2
        for r, c in cells:
            out[r][c] = color
    return out
